mapper.select:
select doctype, doctypename, direction, needconfirmflag, allownegativeflag, remark
  from sdsshop.u_m_doctypeconfig
 where doctype = #{docType}

select doctype, doctypename, direction, needconfirmflag, allownegativeflag, remark from sdsshop.u_m_doctypeconfig where 1 = 1
and doctype = #{docType}
and doctypename like concat('%', #{docTypeName}, '%')
and direction = #{direction}
order by doctype

mapper.insert:
insert into sdsshop.u_m_doctypeconfig(
    doctype, doctypename, direction, needconfirmflag, allownegativeflag, remark
) values(
    #{docType}, #{docTypeName}, #{direction}, #{needConfirmFlag}, #{allowNegativeFlag}, #{remark}
)
